import { chromium } from '@playwright/test'
const ROOT = '/home/zhaodan/work/NodeJsProjects/agent-hub-web'
const browser = await chromium.launch({ args: ['--no-proxy-server'] })

const proto = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await proto.goto(`file://${ROOT}/docs/prototypes/ui-v7-pages.html`)
await proto.waitForTimeout(500)
await proto.evaluate(() => {
  document.querySelectorAll('.page[data-page]').forEach((el) => { el.hidden = el.getAttribute('data-page') !== 'settings' })
})
await proto.waitForTimeout(300)
console.log('proto', await proto.evaluate(() => {
  const t = document.getElementById('instructionText')
  const r = t.getBoundingClientRect()
  const card = document.querySelector('#settings-capabilities .cap-block')
  const cr = card.getBoundingClientRect()
  const head = document.querySelector('.page-head').getBoundingClientRect()
  const acct = document.getElementById('settings-account').getBoundingClientRect()
  const caps = document.getElementById('settings-capabilities').getBoundingClientRect()
  return {
    textarea: { h: r.height, top: r.top, font: getComputedStyle(t).fontSize, lh: getComputedStyle(t).lineHeight, rows: t.rows },
    card: { top: cr.top, h: cr.height },
    head: { top: head.top, h: head.height },
    acct: { top: acct.top, h: acct.height },
    caps: { top: caps.top },
    nav: document.querySelector('.settings-nav-item.is-active')?.getBoundingClientRect().toJSON(),
  }
}))

const dev = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await dev.goto('http://127.0.0.1:5174/login', { waitUntil: 'domcontentloaded' })
await dev.waitForSelector('input', { timeout: 20000 })
await dev.getByPlaceholder('you@example.com').fill('admin@example.com')
